// Registers the service worker generated post-build by scripts/build-sw.mjs
// (see that file for why a plain workbox-build step is used instead of a
// Vite plugin). Imported once from BaseLayout so every page registers it.
// In dev, dist/sw.js doesn't exist (it's only generated by `npm run build`),
// so registration is skipped there rather than erroring.
if ('serviceWorker' in navigator && import.meta.env.PROD) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('/sw.js').catch((err) => {
      console.error('Service worker registration failed:', err);
    });
  });
}
